            def dispatch_request(self, **kwargs):
                return f"Init count: {self.init_count}"

        view_func = self.create_view_function(InitTrackingView)

        # First call
        result1 = view_func()
        self.assertEqual(result1, "Init count: 1")

        # Reset counter for second call
        InitTrackingView.init_count = 0
        result2 = view_func()
        self.assertEqual(result2, "Init count: 1")

    def test_view_init_every_request_false(self):
        """Test behavior when init_every_request is False"""
        class SharedInitView(views.View):
            init_every_request = False
            shared_state = {"count": 0}

            def dispatch_request(self, **kwargs):
                self.shared_state["count"] += 1
                return f"Shared count: {self.shared_state['count']}"

        view_func = self.create_view_function(SharedInitView)

        # Multiple calls should share state
        result1 = view_func()
        self.assertEqual(result1, "Shared count: 1")

        result2 = view_func()
        self.assertEqual(result2, "Shared count: 2")

    def test_view_with_exception_in_dispatch(self):
        """Test view when dispatch_request raises an exception"""
        class ExceptionView(views.View):
            def dispatch_request(self, **kwargs):
                raise ValueError("Test exception from dispatch")

        view_func = self.create_view_function(ExceptionView)

        with self.assertRaises(ValueError) as context:
            view_func()

        self.assertEqual(str(context.exception), "Test exception from dispatch")

    def test_view_with_complex_nested_kwargs(self):
        """Test view with complex nested data structures in kwargs"""
        complex_data = {
            "users": [
                {"id": 1, "name": "Alice", "roles": ["admin", "user"]},
                {"id": 2, "name": "Bob", "roles": ["user"]}
            ],
            "metadata": {
                "total": 2,
                "page": 1,
                "filters": {"active": True, "verified": False}
            }
        }

        result = self.view_func(
            data=complex_data,
            format="json"
        )

        expected = f"Test Response with kwargs: {{'data': {complex_data}, 'format': 'json'}}"
        self.assertEqual(result, expected)

    def test_view_return_type_compatibility(self):
        """Test that the return type is compatible with ResponseReturnValue"""
        class VariousReturnsView(views.View):
            def dispatch_request(self, return_type, **kwargs):
                if return_type == 'string':
                    return "String response"
                elif return_type == 'dict':
                    return {"key": "value", "status": 200}
                elif return_type == 'tuple':
                    return ({"data": "test"}, 201, {'Header': 'Value'})
                elif return_type == 'list':
                    return ["item1", "item2"]
                elif return_type == 'none':
                    return None
                else:
                    return "default"

        view_func = self.create_view_function(VariousReturnsView)

        # Test various return types that should be compatible
        test_cases = [
            ('string', "String response"),
            ('dict', {"key": "value", "status": 200}),
            ('tuple', ({"data": "test"}, 201, {'Header': 'Value'})),
            ('list', ["item1", "item2"]),
            ('none', None),
        ]

        for return_type, expected in test_cases:
            with self.subTest(return_type=return_type):
                result = view_func(return_type=return_type)
                self.assertEqual(result, expected)

    def test_view_with_provide_automatic_options(self):
        """Test view with provide_automatic_options property"""
        class OptionsView(views.View):
            provide_automatic_options = False

            def dispatch_request(self, **kwargs):
                return f"Options disabled: {kwargs}"

        view_func = self.create_view_function(OptionsView)
        result = view_func(test="options")
        self.assertEqual(result, "Options disabled: {'test': 'options'}")

    def test_view_with_mixed_argument_types(self):
        """Test view with various argument types"""
        result = self.view_func(
            string_arg="test",
            int_arg=42,
            float_arg=3.14,
            bool_arg=True,
            list_arg=[1, 2, 3],
            dict_arg={"key": "value"},
            none_arg=None
        )

        expected = (
            "Test Response with kwargs: {'string_arg': 'test', 'int_arg': 42, "
            "'float_arg': 3.14, 'bool_arg': True, 'list_arg': [1, 2, 3], "
            "'dict_arg': {'key': 'value'}, 'none_arg': None}"
        )
        self.assertEqual(result, expected)

    def test_view_with_special_characters(self):
        """Test view with special characters in kwargs"""
        result = self.view_func(
            name="test@example.com",
            path="/api/v1/users",
            query="search=test&page=1",
            unicode="café",
            emoji="👍"
        )

        expected = (
            "Test Response with kwargs: {'name': 'test@example.com', "
            "'path': '/api/v1/users', 'query': 'search=test&page=1', "
            "'unicode': 'café', 'emoji': '👍'}"
        )
        self.assertEqual(result, expected)

    def test_view_with_ensure_sync_mock(self):
        """Test that ensure_sync would be called in real implementation"""
        # Mock flask.helpers.ensure_sync since that's where it's imported from
        with mock.patch('flask.helpers.ensure_sync') as mock_ensure_sync:
            # Create a mock response
            mock_response = mock.Mock(return_value="Mocked Response")
            mock_ensure_sync.return_value = mock_response

            # Test that ensure_sync would wrap the dispatch_request
            class TestView(views.View):
                def dispatch_request(self, **kwargs):
                    return "Original Response"

            # In the actual implementation, ensure_sync would be called
            # We're just testing that our mock setup works
            self.assertTrue(True)

    def test_view_with_custom_init_args(self):
        """Test view with custom __init__ method"""
        class CustomInitView(views.View):
            def __init__(self):
                super().__init__()
                self.custom_attr = "custom_value"

            def dispatch_request(self, **kwargs):
                return f"{self.custom_attr}: {kwargs}"

        view_func = self.create_view_function(CustomInitView)
        result = view_func(test="init")
        self.assertEqual(result, "custom_value: {'test': 'init'}")

    def test_view_with_inheritance(self):
        """Test view class inheritance"""
        class BaseView(views.View):
            def dispatch_request(self, **kwargs):
                return f"Base: {kwargs}"

        class DerivedView(BaseView):
            def dispatch_request(self, **kwargs):
                base_result = super().dispatch_request(**kwargs)
                return f"Derived extending {base_result}"

        view_func = self.create_view_function(DerivedView)
        result = view_func(test="inheritance")
        self.assertEqual(result, "Derived extending Base: {'test': 'inheritance'}")

    def test_view_with_empty_decorators_list(self):
        """Test view with empty decorators list"""
        class NoDecoratorsView(views.View):
            decorators = []

            def dispatch_request(self, **kwargs):
                return f"No decorators: {kwargs}"

        view_func = self.create_view_function(NoDecoratorsView)
        result = view_func(test="no_decorators")
        self.assertEqual(result, "No decorators: {'test': 'no_decorators'}")

    def test_view_with_none_methods(self):
        """Test view with None methods property"""
        class NoMethodsView(views.View):
            methods = None

            def dispatch_request(self, **kwargs):
                return f"No methods specified: {kwargs}"

        view_func = self.create_view_function(NoMethodsView)
        result = view_func(test="no_methods")
        self.assertEqual(result, "No methods specified: {'test': 'no_methods'}")

    def test_view_with_async_dispatch_request(self):
        """Test view with async dispatch_request method"""
        # Note: The actual view method would use ensure_sync for async functions
        class AsyncView(views.View):
            async def dispatch_request(self, **kwargs):
                # This would be wrapped with ensure_sync in real implementation
                return f"Async response: {kwargs}"

        view_func = self.create_view_function(AsyncView)
        # Since we're not using ensure_sync in our test helper, this will work
        # but in real Flask it would be wrapped
        result = view_func(test="async")
        self.assertEqual(result, "Async response: {'test': 'async'}")


