import unittest
import unittest.mock as mock
import click
import typing as t
from flask.cli import AppGroup

class TestAppGroupDecorator(unittest.TestCase):
    def setUp(self):
        """Create an AppGroup instance for testing"""
        self.app_group = AppGroup(name="testgroup")

    def test_decorator_basic_function(self):
        """Test that decorator wraps a simple function correctly"""
        @self.app_group.decorator
        def simple_func():
            return "test result"

        self.assertIsInstance(simple_func, click.Command)
        self.assertEqual(simple_func.name, "simple-func")

    def test_decorator_with_args_kwargs(self):
        """Test decorator with additional args and kwargs"""
        @self.app_group.decorator
        def func_with_params(x: int, y: str = "default"):
            return f"{x}-{y}"

        self.assertIsInstance(func_with_params, click.Command)
        self.assertEqual(func_with_params.name, "func-with-params")

    def test_decorator_preserves_function_signature(self):
        """Test that the original function signature is preserved"""
        def original_func(arg1: str, arg2: int = 10):
            return f"{arg1}-{arg2}"

        decorated = self.app_group.decorator(original_func)

        self.assertIsInstance(decorated, click.Command)
        # The command should have the same name as the function
        self.assertEqual(decorated.name, "original-func")

    def test_decorator_returns_click_command(self):
        """Test that the decorator returns a click.Command instance"""
        def test_func():
            pass

        result = self.app_group.decorator(test_func)
        self.assertIsInstance(result, click.Command)

    def test_decorator_with_wrap_for_ctx(self):
        """Test decorator when wrap_for_ctx is set to True"""
        # Mock the superclass command method to verify wrap_for_ctx is called
        with mock.patch.object(self.app_group, 'command') as mock_command:
            mock_command.return_value = mock.MagicMock(spec=click.Command)

            @self.app_group.decorator
            def wrapped_func():
                return "wrapped"

            # Verify command was called with the function
            mock_command.assert_called_once()

    def test_decorator_with_additional_args(self):
        """Test decorator with positional arguments"""
        def test_func():
            return "test"

        # This should work if command method accepts additional args
        try:
            result = self.app_group.decorator(test_func, "extra_arg")
            self.assertIsInstance(result, click.Command)
        except TypeError:
            # If command doesn't accept extra args, that's expected
            pass

    def test_decorator_with_additional_kwargs(self):
        """Test decorator with keyword arguments"""
        def test_func():
            return "test"

        # This should work if command method accepts additional kwargs
        try:
            result = self.app_group.decorator(test_func, help="Test function")
            self.assertIsInstance(result, click.Command)
        except TypeError:
            # If command doesn't accept extra kwargs, that's expected
            pass

    def test_decorator_non_callable_raises_error(self):
        """Test that decorator raises error with non-callable input"""
        with self.assertRaises(TypeError):
            self.app_group.decorator("not a function")

    def test_decorator_chaining(self):
        """Test that decorator can be used with other decorators"""
        def another_decorator(func):
            func.custom_attr = "decorated"
            return func

        @another_decorator
        @self.app_group.decorator
        def chained_func():
            return "chained"

        self.assertIsInstance(chained_func, click.Command)
        self.assertEqual(chained_func.name, "chained-func")

    def test_decorator_command_invocation(self):
        """Test that the decorated command can be invoked"""
        execution_result = []

        def target_func():
            execution_result.append("executed")
            return "done"

        decorated = self.app_group.decorator(target_func)

        # Simulate command invocation
        ctx = mock.MagicMock()
        decorated.callback(ctx)

        self.assertEqual(execution_result, ["executed"])

    def test_decorator_with_class_method(self):
        """Test decorator with class methods"""
        class TestClass:
            @self.app_group.decorator
            def class_method(self):
                return "class method"

        instance = TestClass()
        # The decorator should still work with bound methods
        self.assertTrue(hasattr(instance.class_method, 'name'))

    def test_decorator_name_generation(self):
        """Test that command names are generated correctly from function names"""
        @self.app_group.decorator
        def function_with_underscores():
            return "test"

        self.assertEqual(function_with_underscores.name, "function-with-underscores")

    def test_multiple_decorations(self):
        """Test decorating multiple functions"""
        @self.app_group.decorator
        def func1():
            return "func1"

        @self.app_group.decorator
        def func2():
            return "func2"

        self.assertIsInstance(func1, click.Command)
        self.assertIsInstance(func2, click.Command)
        self.assertEqual(func1.name, "func1")
        self.assertEqual(func2.name, "func2")

    def test_decorator_with_lambda(self):
        """Test decorator with lambda functions"""
        # Lambdas are callable and should work
        decorated = self.app_group.decorator(lambda: "lambda result")
        self.assertIsInstance(decorated, click.Command)

    def test_decorator_with_callable_class(self):
        """Test decorator with callable classes"""
        class CallableClass:
            def __call__(self):
                return "callable class"

        instance = CallableClass()
        decorated = self.app_group.decorator(instance)
        self.assertIsInstance(decorated, click.Command)

if __name__ == '__main__':
    unittest.main()
